(function(g){'use strict';let id=0;const rows=[];function add(ok,service,message,data=null){const r={id:++id,ok:!!ok,service:String(service||'kernel'),message:String(message||''),data,time:Date.now()};rows.unshift(r);if(rows.length>40)rows.length=40;g.VoidEventBus?.emit('kernel:result',r);return r}g.VoidResultBus={version:'2.0.0',success:(s,m,d)=>add(true,s,m,d),failure:(s,m,d)=>add(false,s,m,d),latest:()=>rows.slice(),clear:()=>{rows.length=0}}})(window);
